import{_ as n,o as a,c as p,a3 as t}from"./chunks/framework.bijRUqYl.js";const g=JSON.parse('{"title":"法律与财税提示词模板","description":"法律与财税行业的 5 条提示词模板：合同初审要点、条款翻译、事项时间线、资料清单、内部制度。含合规边界。","frontmatter":{"title":"法律与财税提示词模板","description":"法律与财税行业的 5 条提示词模板：合同初审要点、条款翻译、事项时间线、资料清单、内部制度。含合规边界。"},"headers":[],"relativePath":"community/prompts/法律与财税.md","filePath":"community/prompts/法律与财税.md"}'),e={name:"community/prompts/法律与财税.md"};function o(l,s,i,r,c,u){return a(),p("div",null,[...s[0]||(s[0]=[t(`<h1 id="⚖️-法律与财税-·-5-条提示词模板" tabindex="-1">⚖️ 法律与财税 · 5 条提示词模板 <a class="header-anchor" href="#⚖️-法律与财税-·-5-条提示词模板" aria-label="Permalink to &quot;⚖️ 法律与财税 · 5 条提示词模板&quot;">​</a></h1><blockquote><p>⚠️ <strong>一句话定位</strong>：AI 在这行是<strong>助理</strong>，不是<strong>执业者</strong>。 它能帮你<strong>整理、检索线索、把专业话翻译成人话、列清单</strong>； 它<strong>不能</strong>出法律意见、下税务结论、替你签字。 这一页所有模板都带&quot;边界句&quot;，<strong>请保留</strong>。</p></blockquote><h2 id="本行三句话骨架" tabindex="-1">本行三句话骨架 <a class="header-anchor" href="#本行三句话骨架" aria-label="Permalink to &quot;本行三句话骨架&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我是【律师 / 法务 / 会计 / 代账】，手上有【什么事】，依据是【哪部法 / 哪个税种 / 哪个地区】。</span></span>
<span class="line"><span>帮我产出【要点清单 / 时间线 / 说明稿】，形式【…】。</span></span>
<span class="line"><span>规矩：只做梳理与提示，不出具结论性意见；法条与政策必须由我提供原文，不许凭记忆引用。</span></span></code></pre></div><hr><h2 id="_1-·-合同初审-风险点清单-不是出法律意见" tabindex="-1">1 · 合同初审：风险点清单（不是出法律意见） <a class="header-anchor" href="#_1-·-合同初审-风险点清单-不是出法律意见" aria-label="Permalink to &quot;1 · 合同初审：风险点清单（不是出法律意见）&quot;">​</a></h2><p><strong>什么时候用</strong>：一份合同来了，你要先快速扫出&quot;哪几条要改、哪几条要问&quot;。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>合同类型：【买卖合同 / 服务合同 / 劳动合同 / 租赁合同 / 合作协议】</span></span>
<span class="line"><span>我的立场：【甲方 / 乙方 / 第三方】</span></span>
<span class="line"><span>这份合同全文：</span></span>
<span class="line"><span>【粘贴全文】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我出一份&quot;初审要点清单&quot;（不是法律意见），按这个结构：</span></span>
<span class="line"><span>① 关键条款一览（付款、交付、违约、终止、争议解决、知识产权、保密）各自在多少条，写了什么</span></span>
<span class="line"><span>② 对我方明显不利的条款（引用原文条款号，说明&quot;不利在哪&quot;，不说明&quot;是否有效&quot;）</span></span>
<span class="line"><span>③ 缺失的常见条款（这一类合同通常会有、但这份没有的）</span></span>
<span class="line"><span>④ 需要向对方确认的问题清单（写成我可以直接发给对方的问句）</span></span>
<span class="line"><span>⑤ 我复核时最容易漏看的地方</span></span>
<span class="line"><span>规矩：不许引用我没提供的法条；不许下&quot;该条款无效/有效&quot;这类结论；不确定的一律写&quot;需人工判断&quot;。</span></span></code></pre></div><p><strong>它给你</strong>：一份结构化的初审清单。<strong>结论永远由你出。</strong></p><hr><h2 id="_2-·-把条款翻译成人话-给客户-老板解释" tabindex="-1">2 · 把条款翻译成人话（给客户 / 老板解释） <a class="header-anchor" href="#_2-·-把条款翻译成人话-给客户-老板解释" aria-label="Permalink to &quot;2 · 把条款翻译成人话（给客户 / 老板解释）&quot;">​</a></h2><p><strong>什么时候用</strong>：客户看着合同一脸茫然，你要用三分钟让他明白&quot;这条对你意味着什么&quot;。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>客户情况：【自然人 / 小微企业主 / 公司，懂不懂行业术语】</span></span>
<span class="line"><span>需要解释的条款：【粘贴原文】</span></span>
<span class="line"><span>客户最关心的是：【…】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我写一段口头解释（口语，200 字内）：</span></span>
<span class="line"><span>① 先说&quot;这条其实在说什么&quot;（去掉法律术语）</span></span>
<span class="line"><span>② 再说&quot;对你来说意味着什么&quot;（举一个具体的小场景）</span></span>
<span class="line"><span>③ 最后说&quot;所以我会建议你怎么做&quot;（留出选择，不替他决定）</span></span>
<span class="line"><span>再给我一个&quot;如果对方不同意改，还有哪些备选方案&quot;的清单（只列方向，不写结论）。</span></span>
<span class="line"><span>规矩：不做胜诉率判断、不给结果承诺；解释中不添加我未提供的条款内容。</span></span></code></pre></div><p><strong>它给你</strong>：一段人话解释 + 备选方向。</p><hr><h2 id="_3-·-事项-案件时间线梳理" tabindex="-1">3 · 事项 / 案件时间线梳理 <a class="header-anchor" href="#_3-·-事项-案件时间线梳理" aria-label="Permalink to &quot;3 · 事项 / 案件时间线梳理&quot;">​</a></h2><p><strong>什么时候用</strong>：材料一堆（聊天记录、邮件、转账截图、合同），要快速看出&quot;事情是怎么一步步走到今天的&quot;。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>材料（已脱敏）：</span></span>
<span class="line"><span>【按顺序粘贴：日期 + 谁 + 做了什么 + 出处（哪条消息/哪份文件）】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我：</span></span>
<span class="line"><span>① 做一条时间线（日期 / 事件 / 出处），按时间排序；日期不明的单独列一区</span></span>
<span class="line"><span>② 标出&quot;关键节点&quot;（改变了法律或经济关系的那些事）</span></span>
<span class="line"><span>③ 列出&quot;时间线里说不清的地方&quot;（缺哪一环、需要补什么证据）</span></span>
<span class="line"><span>④ 按&quot;对我方有利 / 不利 / 中性&quot;给每个节点分类</span></span>
<span class="line"><span>规矩：只整理我给的材料，不推测未记录的事实；每一条都必须能追溯到出处，不许补全。</span></span></code></pre></div><p><strong>它给你</strong>：一条可追溯的时间线 + 待补证据清单。</p><hr><h2 id="_4-·-财税资料清单与催收提醒" tabindex="-1">4 · 财税资料清单与催收提醒 <a class="header-anchor" href="#_4-·-财税资料清单与催收提醒" aria-label="Permalink to &quot;4 · 财税资料清单与催收提醒&quot;">​</a></h2><p><strong>什么时候用</strong>：每个月都在追客户要票、要流水、要资料，催得自己都尴尬。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我的身份：【代账会计 / 企业财务】</span></span>
<span class="line"><span>这个月要给【…家客户】办【什么事项，例如&quot;小规模纳税人申报&quot;】</span></span>
<span class="line"><span>每家的特殊情况：【…（例如某家本季度有新开票、某家有人员变动）】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我：</span></span>
<span class="line"><span>① 做一张&quot;分客户资料清单表&quot;（客户 / 需要什么资料 / 截止日 / 已收到没有）</span></span>
<span class="line"><span>② 写 3 版催收消息（第一次提醒 / 第二次提醒 / 最后一天紧急提醒），语气依次升级但不失礼</span></span>
<span class="line"><span>③ 写一段&quot;为什么需要这些资料&quot;的解释（发给不懂财税的客户看，让他知道不是你在为难他）</span></span>
<span class="line"><span>规矩：不引用我没提供的税率、政策文号和申报期限；地区差异一律标&quot;以你们当地口径为准&quot;。</span></span></code></pre></div><p><strong>它给你</strong>：资料清单表 + 3 版催收话术 + 解释稿。<strong>解释稿是留客的关键</strong>。</p><hr><h2 id="_5-·-内部制度-通知-说明文撰写" tabindex="-1">5 · 内部制度 / 通知 / 说明文撰写 <a class="header-anchor" href="#_5-·-内部制度-通知-说明文撰写" aria-label="Permalink to &quot;5 · 内部制度 / 通知 / 说明文撰写&quot;">​</a></h2><p><strong>什么时候用</strong>：要写一份内部制度、一份对外说明、一份风险提示，不能太法律化也不能太随意。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>要写的是：【制度 / 通知 / 给客户的说明 / 风险提示】</span></span>
<span class="line"><span>对象：【公司员工 / 客户 / 合作方】，他们的理解水平：【…】</span></span>
<span class="line"><span>必须包含的内容：【123…】</span></span>
<span class="line"><span>我们绝对不能写的内容：【…（例如不能承诺、不能出现某表述）】</span></span>
<span class="line"><span>参考的现有文件：【有就粘贴】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我写一份初稿，并额外给我：</span></span>
<span class="line"><span>① 一份&quot;这条可能被误解成什么&quot;的自查清单</span></span>
<span class="line"><span>② 一份&quot;如果对方据此主张权利，我们哪句话会吃亏&quot;的提示</span></span>
<span class="line"><span>③ 一句话版本（用于群里快速通知）</span></span>
<span class="line"><span>规矩：不做法律结论；不添加我没给的权利义务；涉及具体责任的表述一律标&quot;需律师确认&quot;。</span></span></code></pre></div><p><strong>它给你</strong>：初稿 + 两个自查清单 + 一句话版本。</p><hr><h2 id="⚠️-这行的红线" tabindex="-1">⚠️ 这行的红线 <a class="header-anchor" href="#⚠️-这行的红线" aria-label="Permalink to &quot;⚠️ 这行的红线&quot;">​</a></h2><ol><li><strong>不出具结论性意见</strong>：有效/无效、胜诉/败诉、能不能抵扣、罚不罚——这些必须是执业人判断，AI 只能列线索。</li><li><strong>法条与政策不许凭记忆引用</strong>：AI 引用的法条<strong>经常是错的或过期的</strong>。要用，就把原文粘给它，或者自己核实。<strong>这条是这行最大的坑。</strong></li><li><strong>不许用 AI 生成的内容对外署名</strong>：给客户的意见书、鉴证报告，必须经执业人复核并署名。</li><li><strong>当事人信息必须脱敏</strong>：真实姓名、身份证、银行账号、案号，处理前一律替换。</li><li><strong>地区差异必须自己确认</strong>：税务、社保、政策，各地口径不同，AI 给的是&quot;常见做法&quot;，不是&quot;你们当地的规定&quot;。</li></ol><hr><p><strong>目录</strong>：<a href="/MoMAWork-/community/prompts/">← 回到行业提示词模板库</a> ｜ 下一个行业 → <strong><a href="/MoMAWork-/community/prompts/销售与客户跟进.html">销售与客户跟进</a></strong></p>`,34)])])}const d=n(e,[["render",o]]);export{g as __pageData,d as default};
